<script setup>
const props=defineProps({modelValue:Object,allowAssessmentNeed:{type:Boolean,default:false}});const emit=defineEmits(['update:modelValue'])
const set=(key,val)=>emit('update:modelValue',{...props.modelValue,[key]:val})
const lists=[['diagnoses','确定诊断'],['suspected','疑似诊断'],['treatments','当前治疗措施'],['historical','既往治疗'],['suggestions','护理建议（AI推断，需核对）'],['evidence','原文证据 / 时间状态']]
</script>
<template><el-form label-position="top"><div class="form-grid"><el-form-item label="患者名称 *"><el-input :model-value="modelValue.name" @update:model-value="v=>set('name',v)"/></el-form-item><el-form-item label="性别"><el-select :model-value="modelValue.gender" @update:model-value="v=>set('gender',v)"><el-option value="男"/><el-option value="女"/><el-option value="" label="未说明"/></el-select></el-form-item><el-form-item label="年龄"><el-input-number :model-value="modelValue.age" @update:model-value="v=>set('age',v??null)" :min="0" :max="130"/></el-form-item><el-form-item label="人工核对护理负荷 *"><el-select :model-value="modelValue.load" @update:model-value="v=>set('load',v)" placeholder="请选择"><el-option value="light" label="较轻"/><el-option value="medium" label="稍重"/><el-option value="high" label="高负荷"/></el-select></el-form-item><el-form-item v-if="allowAssessmentNeed" label="病情评估支持需求（人工核对）"><el-select :model-value="modelValue.assessment_need||''" @update:model-value="v=>set('assessment_need',v)"><el-option value="" label="待核对"/><el-option value="higher" label="需较高评估支持"/><el-option value="standard" label="未标记较高需求"/></el-select><small>独立于护理负荷；请根据临床资料人工判断。</small></el-form-item></div><el-form-item v-for="[key,label] in lists" :key="key" :label="label+'（多项用分号分隔）'"><el-input :model-value="(modelValue[key]||[]).join('；')" @update:model-value="v=>set(key,v.split(/[；;\n]/).map(x=>x.trim()).filter(Boolean))" type="textarea" :rows="key==='evidence'?3:2"/></el-form-item></el-form></template>
